'use strict';
(() => {
  const C=LedCore,$=id=>document.getElementById(id),KEY='uno-q-led-studio-v1';
  let project={version:1,mode:'gray',loop:true,speed:1,frames:[C.blank()]},active=0,tool='pen',brush=7;
  let undoStack=[],redoStack=[],stroke=null,playing=false,playFrame=0,elapsed=0,lastTick=0,raf=0,toastTimer,images=[];
  const heart=['0001100011000','0011110111100','0111111111110','0111111111110','0011111111100','0001111111000','0000111110000','0000011100000'];
  project.frames[0].pixels=heart.join('').split('').map(v=>Number(v)*7);
  try{const saved=localStorage.getItem(KEY);if(saved)project=C.validate(JSON.parse(saved));}catch(e){toast('저장한 작업을 읽지 못해 새 작업을 열었습니다.');}
  const cells=[];
  for(let i=0;i<C.N;i++){const b=document.createElement('button');b.type='button';b.className='pixel';b.dataset.index=i;b.setAttribute('aria-label',`${Math.floor(i/C.W)+1}행 ${i%C.W+1}열`);b.addEventListener('click',e=>{if(e.detail===0){edit(()=>{const v=tool==='eraser'?0:project.mode==='binary'?7:brush;project.frames[active].pixels[i]=project.frames[active].pixels[i]===v?0:v;});}});$('matrix').append(b);cells.push(b);}
  function toast(msg){$('toast').textContent=msg;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),3500);}
  function snapshot(){return JSON.stringify({project,active});}
  function history(before){if(before!==snapshot()){undoStack.push(before);if(undoStack.length>60)undoStack.shift();redoStack=[];}save();render();}
  function save(){try{localStorage.setItem(KEY,JSON.stringify(project));$('saved').textContent='이 브라우저에 자동 저장됨';}catch(e){$('saved').textContent='자동 저장 불가 · 프로젝트를 저장하세요';}}
  function edit(fn){finishStroke();pause();const before=snapshot();fn();elapsed=0;playFrame=active;history(before);}
  function restore(data){const s=JSON.parse(data);project=C.validate(s.project);active=Math.max(0,Math.min(project.frames.length-1,s.active));playFrame=active;elapsed=0;save();render();}
  function undo(){finishStroke();pause();if(!undoStack.length)return;redoStack.push(snapshot());restore(undoStack.pop());}
  function redo(){finishStroke();pause();if(!redoStack.length)return;undoStack.push(snapshot());restore(redoStack.pop());}
  function drawLed(canvas,pixels){const ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height;ctx.clearRect(0,0,w,h);ctx.fillStyle='#070c13';ctx.fillRect(0,0,w,h);const unit=Math.min(w/C.W,h/C.H),ox=(w-unit*C.W)/2,oy=(h-unit*C.H)/2;pixels.forEach((v,i)=>{ctx.beginPath();ctx.arc(ox+(i%C.W+.5)*unit,oy+(Math.floor(i/C.W)+.5)*unit,unit*.22,0,Math.PI*2);ctx.shadowBlur=v?unit*.3:0;ctx.shadowColor='#318bff';ctx.fillStyle=v?`rgb(${Math.round(20+55*v/7)},${Math.round(50+120*v/7)},${Math.round(80+175*v/7)})`:'#18283d';ctx.fill();});ctx.shadowBlur=0;}
  function paintCanvas(){const p=project.frames[active].pixels;cells.forEach((b,i)=>{b.style.setProperty('--level',p[i]/7);b.setAttribute('aria-pressed',String(p[i]>0));b.setAttribute('aria-label',`${Math.floor(i/C.W)+1}행 ${i%C.W+1}열, 밝기 ${p[i]}`);});$('litCount').textContent=`${p.filter(Boolean).length} / 104 켜짐`;if(!playing){drawLed($('preview'),p);$('playIndex').textContent=`${String(active+1).padStart(2,'0')} / ${String(project.frames.length).padStart(2,'0')}`;}}
  function render(){paintCanvas();$('frameLabel').textContent=`프레임 ${String(active+1).padStart(2,'0')}`;$('mode').value=project.mode;$('loop').checked=project.loop;$('speed').value=project.speed;$('duration').value=project.frames[active].duration;$('brushLabel').hidden=project.mode==='binary';$('undo').disabled=!undoStack.length;$('redo').disabled=!redoStack.length;$('moveLeft').disabled=active===0;$('moveRight').disabled=active===project.frames.length-1;$('deleteFrame').disabled=project.frames.length===1;$('addFrame').disabled=$('duplicate').disabled=project.frames.length>=C.MAX;$('totalTime').textContent=`${project.frames.length}개 · ${(project.frames.reduce((n,f)=>n+Math.max(1,Math.round(f.duration/project.speed)),0)/1000).toFixed(2)}초`;
    $('frames').replaceChildren();project.frames.forEach((f,i)=>{const b=document.createElement('button');b.className='frame-card'+(i===active?' selected':'');b.setAttribute('aria-pressed',String(i===active));b.setAttribute('aria-label',`프레임 ${i+1}, ${f.duration}밀리초`);const c=document.createElement('canvas');c.width=195;c.height=120;drawLed(c,f.pixels);const s=document.createElement('span'),n=document.createElement('strong'),d=document.createElement('span');n.textContent=String(i+1).padStart(2,'0');d.textContent=f.duration+'ms';s.append(n,d);b.append(c,s);b.onclick=()=>{finishStroke();pause();active=i;playFrame=i;elapsed=0;render();};$('frames').append(b);});
  }
  function locate(e){const hit=document.elementFromPoint(e.clientX,e.clientY);return hit&&hit.classList.contains('pixel')?Number(hit.dataset.index):-1;}
  function applyPixel(i){project.frames[active].pixels[i]=stroke.value;}
  function line(a,b){let x=a%C.W,y=Math.floor(a/C.W),tx=b%C.W,ty=Math.floor(b/C.W),dx=Math.abs(tx-x),dy=-Math.abs(ty-y),sx=x<tx?1:-1,sy=y<ty?1:-1,err=dx+dy;while(true){applyPixel(y*C.W+x);if(x===tx&&y===ty)break;const e=2*err;if(e>=dy){err+=dy;x+=sx;}if(e<=dx){err+=dx;y+=sy;}}}
  function finishStroke(){if(!stroke)return;const before=stroke.before;stroke=null;history(before);}
  $('matrix').addEventListener('pointerdown',e=>{if(e.button!==0)return;const i=locate(e);if(i<0)return;e.preventDefault();pause();elapsed=0;playFrame=active;const v=tool==='eraser'?0:project.mode==='binary'?7:brush;stroke={before:snapshot(),value:tool==='pen'&&project.frames[active].pixels[i]===v?0:v,last:i,pointer:e.pointerId};$('matrix').setPointerCapture(e.pointerId);applyPixel(i);paintCanvas();});
  $('matrix').addEventListener('pointermove',e=>{if(!stroke||stroke.pointer!==e.pointerId)return;const i=locate(e);if(i>=0){line(stroke.last,i);stroke.last=i;paintCanvas();}});
  for(const event of ['pointerup','pointercancel','lostpointercapture'])$('matrix').addEventListener(event,finishStroke);
  function setTool(next){tool=next;for(const t of ['pen','eraser']){$(t).classList.toggle('selected',t===tool);$(t).setAttribute('aria-pressed',String(t===tool));}}
  $('pen').onclick=()=>setTool('pen');$('eraser').onclick=()=>setTool('eraser');$('brush').oninput=()=>{brush=Number($('brush').value);$('brushValue').value=brush;};$('undo').onclick=undo;$('redo').onclick=redo;
  $('flipX').onclick=()=>edit(()=>project.frames[active].pixels=C.flip(project.frames[active].pixels,false));$('flipY').onclick=()=>edit(()=>project.frames[active].pixels=C.flip(project.frames[active].pixels,true));$('invert').onclick=()=>edit(()=>project.frames[active].pixels=project.frames[active].pixels.map(v=>7-v));$('clear').onclick=()=>edit(()=>project.frames[active].pixels.fill(0));
  $('mode').onchange=()=>edit(()=>{project.mode=$('mode').value;if(project.mode==='binary')for(const f of project.frames)f.pixels=f.pixels.map(v=>v>=4?7:0);});
  function addFrame(copy){if(project.frames.length>=C.MAX)return toast('최대 200개 프레임까지 사용할 수 있습니다.');edit(()=>{project.frames.splice(active+1,0,copy?JSON.parse(JSON.stringify(project.frames[active])):C.blank());active++;});$('frames').children[active]?.scrollIntoView({block:'nearest',inline:'nearest'});}
  $('addFrame').onclick=()=>addFrame(false);$('duplicate').onclick=()=>addFrame(true);$('deleteFrame').onclick=()=>{if(project.frames.length>1)edit(()=>{project.frames.splice(active,1);active=Math.min(active,project.frames.length-1);});};
  function move(delta){const next=active+delta;if(next<0||next>=project.frames.length)return;edit(()=>{[project.frames[active],project.frames[next]]=[project.frames[next],project.frames[active]];active=next;});}
  $('moveLeft').onclick=()=>move(-1);$('moveRight').onclick=()=>move(1);$('duration').onchange=()=>{const n=Number($('duration').value);if(!Number.isInteger(n)||n<20||n>60000){$('duration').value=project.frames[active].duration;toast('표시 시간은 20~60000ms 사이의 정수로 입력하세요.');return;}edit(()=>project.frames[active].duration=n);};$('loop').onchange=()=>edit(()=>project.loop=$('loop').checked);$('speed').onchange=()=>edit(()=>project.speed=Number($('speed').value));
  function pause(){playing=false;cancelAnimationFrame(raf);$('play').textContent='▶ 재생';}
  function showPlaying(){drawLed($('preview'),project.frames[playFrame].pixels);$('playIndex').textContent=`${String(playFrame+1).padStart(2,'0')} / ${String(project.frames.length).padStart(2,'0')}`;}
  function tick(now){if(!playing)return;elapsed+=now-lastTick;lastTick=now;let steps=0;while(elapsed>=Math.max(1,Math.round(project.frames[playFrame].duration/project.speed))&&steps++<1000){elapsed-=Math.max(1,Math.round(project.frames[playFrame].duration/project.speed));if(playFrame+1<project.frames.length)playFrame++;else if(project.loop)playFrame=0;else{pause();elapsed=0;active=playFrame;render();return;}}showPlaying();raf=requestAnimationFrame(tick);}
  $('play').onclick=()=>{finishStroke();if(playing){pause();return;}if(!project.loop&&playFrame===project.frames.length-1&&elapsed===0)playFrame=0;playing=true;lastTick=performance.now();$('play').textContent='Ⅱ 일시정지';showPlaying();raf=requestAnimationFrame(tick);};$('stop').onclick=()=>{pause();active=playFrame=0;elapsed=0;render();};
  document.addEventListener('visibilitychange',()=>{if(document.hidden&&playing){pause();toast('화면을 떠나 재생을 일시정지했습니다.');}});
  function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);}
  $('saveProject').onclick=()=>{finishStroke();download('uno-q-project.json',JSON.stringify(project,null,2),'application/json');toast('프로젝트를 저장했습니다.');};$('loadProject').onclick=()=>$('projectInput').click();
  $('projectInput').onchange=async()=>{const file=$('projectInput').files[0];$('projectInput').value='';if(!file)return;try{if(file.size>2000000)throw Error('프로젝트 파일은 2MB 이하만 열 수 있습니다.');const incoming=C.validate(JSON.parse(await file.text()));edit(()=>{project=incoming;active=0;});toast('프로젝트를 불러왔습니다.');}catch(e){toast(e instanceof SyntaxError?'프로젝트 JSON 파일을 확인하세요.':e.message);}};
  function openCode(){finishStroke();pause();$('code').value=C.generate(project);$('codeDialog').showModal();}
  $('export').onclick=$('exportSide').onclick=openCode;$('downloadCode').onclick=()=>download('sketch.ino',C.generate(project),'text/plain;charset=utf-8');$('copyCode').onclick=async()=>{try{await navigator.clipboard.writeText($('code').value);toast('코드를 복사했습니다.');}catch(e){$('code').focus();$('code').select();try{if(document.execCommand('copy'))return toast('코드를 복사했습니다.');}catch(e){}toast('코드를 선택했습니다. Ctrl/⌘+C로 복사하세요.');}};
  document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(b.dataset.close).close());
  $('importImage').onclick=()=>$('imageInput').click();
  async function decode(file){if(!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('PNG, JPG, WebP 이미지를 선택하세요.');if(file.size>20*1024*1024)throw Error('이미지 하나의 크기는 20MB 이하로 선택하세요.');return await new Promise((resolve,reject)=>{const url=URL.createObjectURL(file),img=new Image();img.onload=()=>{URL.revokeObjectURL(url);if(img.width*img.height>40000000)return reject(Error('이미지는 4천만 픽셀 이하로 줄여주세요.'));resolve({img,name:file.name});};img.onerror=()=>{URL.revokeObjectURL(url);reject(Error('이미지를 읽지 못했습니다. 다른 파일을 선택하세요.'));};img.src=url;});}
  $('imageInput').onchange=async()=>{const files=[...$('imageInput').files];$('imageInput').value='';if(!files.length)return;if(files.length>C.MAX)return toast('한 번에 최대 200개 이미지를 선택하세요.');$('importImage').disabled=true;try{const loaded=[];for(const f of files)loaded.push(await decode(f));images=loaded;for(const id of ['offsetX','offsetY'])$(id).value=0;$('zoom').value=1;$('imageInvert').checked=false;$('importTarget').value=files.length>1?'append':'replace';$('importTarget').disabled=files.length>1;$('threshold').disabled=project.mode!=='binary';$('imageName').textContent=files.length>1?`${files[0].name} 외 ${files.length-1}개 · 첫 이미지 미리보기`:files[0].name;finishStroke();pause();imagePreview();$('imageDialog').showModal();}catch(e){toast(e.message);}finally{$('importImage').disabled=false;}};
  function convert(img){const canvas=document.createElement('canvas');canvas.width=C.W;canvas.height=C.H;const ctx=canvas.getContext('2d',{willReadFrequently:true}),base=$('fit').value==='cover'?Math.max(C.W/img.width,C.H/img.height):Math.min(C.W/img.width,C.H/img.height),scale=base*Number($('zoom').value),w=img.width*scale,h=img.height*scale,x=(C.W-w)/2+Number($('offsetX').value)/100*Math.max(C.W,w)/2,y=(C.H-h)/2+Number($('offsetY').value)/100*Math.max(C.H,h)/2;ctx.imageSmoothingEnabled=true;ctx.imageSmoothingQuality='high';ctx.drawImage(img,x,y,w,h);return C.quantize(ctx.getImageData(0,0,C.W,C.H).data,project.mode,Number($('threshold').value),$('imageInvert').checked);}
  function imagePreview(){if(!images.length)return;drawLed($('imagePreview'),convert(images[0].img));$('thresholdValue').value=$('threshold').value;}
  for(const id of ['fit','zoom','offsetX','offsetY','threshold','imageInvert'])$(id).addEventListener('input',imagePreview);
  $('applyImage').onclick=()=>{const append=$('importTarget').value==='append';if(project.frames.length+(append?images.length:images.length-1)>C.MAX)return toast('프레임은 최대 200개입니다. 일부 프레임을 삭제한 뒤 다시 시도하세요.');try{const frames=images.map(({img})=>({pixels:convert(img),duration:project.frames[active].duration}));edit(()=>{if(append){const start=active+1;project.frames.splice(start,0,...frames);active=start;}else{project.frames.splice(active,1,...frames);}});$('imageDialog').close();toast(`${frames.length}개 이미지를 적용했습니다.`);}catch(e){toast('변환에 실패했습니다. 이미지를 다시 선택하세요.');}};
  $('imageDialog').addEventListener('close',()=>{images=[];});
  document.addEventListener('keydown',e=>{if(e.target.matches('input,textarea,select')||document.querySelector('dialog[open]'))return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo();}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();$('saveProject').click();}});
  if(document.modelContext?.registerTool){const life=new AbortController();const register=t=>{try{Promise.resolve(document.modelContext.registerTool(t,{signal:life.signal})).catch(()=>{});}catch(e){}};
    register({name:'read_led_project',description:'Read the current 13 by 8 LED animation project.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>JSON.parse(JSON.stringify(project))});
    register({name:'replace_led_project',description:'Replace the visible LED project with validated frame data. This is undoable.',inputSchema:{type:'object',properties:{project:{type:'object'}},required:['project'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{const p=C.validate(input.project);edit(()=>{project=p;active=0;});return {frames:project.frames.length,mode:project.mode};}});
    register({name:'generate_app_lab_code',description:'Generate an Arduino UNO Q App Lab sketch for the current project.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({filename:'sketch.ino',code:C.generate(project)})});
    addEventListener('pagehide',()=>life.abort(),{once:true});
  }
  const baseRender=render;
  render=function(){baseRender();cells.forEach((b,i)=>b.style.setProperty('--ghost',$('onion').checked&&active>0?project.frames[active-1].pixels[i]/7*.25:0));};
  $('onion').onchange=render;
  render();save();
})();
